{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.core_tshirts_replenishment AS WITH sku_list AS ( SELECT TRIM(UPPER(column1)) AS SKU_GROUP, TRIM(UPPER(column2)) AS SKU_FAMILY, column3 AS TYPE, column4 AS SUBTYPE FROM (VALUES (\'4PL002-01\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-02\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-03\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-04\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-05\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-06\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-07\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-08\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-09\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-10\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL002-11\',\'4PL002\',\'Polo\',\'Regular Fit Cotton\'), (\'4PL003-01\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-02\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-03\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-04\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-05\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL003-06\',\'4PL003\',\'Polo\',\'Slim Fit 100%\'), (\'4PL004-01\',\'4PL004\',\'Polo\',\'Oversized Cotton\'), (\'4PL004-03\',\'4PL004\',\'Polo\',\'Oversized Cotton\'), (\'4PL011-01\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-02\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-03\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-04\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-05\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4PL011-06\',\'4PL011\',\'Polo\',\'Zipper Cotton\'), (\'4RN001-01\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-02\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-03\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-04\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN001-05\',\'4RN001\',\'Sleeveless\',\'Sleeveless\'), (\'4RN002-01\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-02\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-03\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-04\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-05\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-06\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-07\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-08\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-09\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-10\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN002-11\',\'4RN002\',\'Round Neck\',\'Oversized Cotton\'), (\'4RN003-01\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-02\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-03\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-04\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-05\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-06\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-07\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-08\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-09\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-10\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-11\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-12\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-13\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-14\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN003-15\',\'4RN003\',\'Round Neck\',\'Regular Fit Cotton\'), (\'4RN005-01\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-02\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-03\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-04\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-05\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-06\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-07\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-08\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-09\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-10\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\'), (\'4RN005-11\',\'4RN005\',\'Round Neck\',\'Slim Fit Stretch\') ) ), bp AS ( SELECT UPPER(TRIM(b.SKU_GROUP)) AS SKU_GROUP, b.TITLE, b.IMAGE_URL, b.FINAL_SKU_CLASS, b.ONLINE_INVENTORY AS WH_INVENTORY, b.ONLINE_XS_UNITS, b.ONLINE_S_UNITS, b.ONLINE_M_UNITS, b.ONLINE_L_UNITS, b.ONLINE_XL_UNITS, b.ONLINE_XXL_UNITS, b.ONLINE_XL3_UNITS, b.ONLINE_XL4_UNITS, b.ONLINE_XL5_UNITS, b.ONLINE_XL6_UNITS FROM snitch_db.maplemonk.base_product b INNER JOIN sku_list s ON UPPER(TRIM(b.SKU_GROUP)) = s.SKU_GROUP ), wh_size AS ( SELECT SKU_GROUP, \'XS\' AS SIZE, ONLINE_XS_UNITS AS WH_QTY FROM bp UNION ALL SELECT SKU_GROUP, \'S\', ONLINE_S_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'M\', ONLINE_M_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'L\', ONLINE_L_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'XL\', ONLINE_XL_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'XXL\',ONLINE_XXL_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'3XL\',ONLINE_XL3_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'4XL\',ONLINE_XL4_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'5XL\',ONLINE_XL5_UNITS FROM bp UNION ALL SELECT SKU_GROUP, \'6XL\',ONLINE_XL6_UNITS FROM bp ), store_rollup AS ( SELECT UPPER(TRIM(o.SKU_GROUP)) AS SKU_GROUP, SUM(o.INVENTORY) AS TOTAL_STORE_INVENTORY, SUM(o.FINAL_ROS) AS SUM_DAILY_ROS FROM snitch_db.maplemonk.offline_master o INNER JOIN sku_list s ON UPPER(TRIM(o.SKU_GROUP)) = s.SKU_GROUP GROUP BY UPPER(TRIM(o.SKU_GROUP)) ), hist_sales AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, UPPER(SIZE) AS SIZE, SUM(SUBORDER_QUANTITY) AS UNITS_SOLD_90D FROM snitch_db.maplemonk.store_fact_items_offline WHERE ORDER_DATE >= DATEADD(day, -90, CURRENT_DATE()) AND UPPER(TRIM(SKU_GROUP)) IN (SELECT SKU_GROUP FROM sku_list) AND COALESCE(RETURN_FLAG, \'N\') NOT IN (\'Y\',\'Yes\',\'TRUE\',\'True\',\'1\') GROUP BY UPPER(TRIM(SKU_GROUP)), UPPER(SIZE) ), hist_mix AS ( SELECT SKU_GROUP, SIZE, UNITS_SOLD_90D, UNITS_SOLD_90D * 1.0 / NULLIF(SUM(UNITS_SOLD_90D) OVER (PARTITION BY SKU_GROUP), 0) AS HIST_MIX_PCT FROM hist_sales ), sku_po AS ( SELECT s.SKU_GROUP, s.SKU_FAMILY, s.TYPE, s.SUBTYPE, bp.TITLE, bp.IMAGE_URL, bp.FINAL_SKU_CLASS, COALESCE(bp.WH_INVENTORY, 0) AS WH_INVENTORY, COALESCE(r.TOTAL_STORE_INVENTORY, 0) AS TOTAL_STORE_INVENTORY, COALESCE(bp.WH_INVENTORY, 0) + COALESCE(r.TOTAL_STORE_INVENTORY, 0) AS TOTAL_INVENTORY, COALESCE(r.SUM_DAILY_ROS, 0) AS SUM_DAILY_ROS, ROUND(COALESCE(r.SUM_DAILY_ROS, 0) * 90, 0) AS DEMAND_90D, GREATEST( ROUND(COALESCE(r.SUM_DAILY_ROS, 0) * 90, 0) - COALESCE(bp.WH_INVENTORY, 0) - COALESCE(r.TOTAL_STORE_INVENTORY, 0), 0 ) AS PO_QTY_TOTAL FROM sku_list s LEFT JOIN bp ON bp.SKU_GROUP = s.SKU_GROUP LEFT JOIN store_rollup r ON r.SKU_GROUP = s.SKU_GROUP ), size_calc AS ( SELECT p.*, ws.SIZE, COALESCE(hm.UNITS_SOLD_90D, 0) AS HIST_SOLD_90D, COALESCE(hm.HIST_MIX_PCT, 0) AS HIST_MIX_PCT, COALESCE(ws.WH_QTY, 0) AS CURRENT_WH_QTY, ROUND(COALESCE(hm.HIST_MIX_PCT, 0) * (p.WH_INVENTORY + p.PO_QTY_TOTAL), 0) AS TARGET_POST_PO_QTY, GREATEST( ROUND(COALESCE(hm.HIST_MIX_PCT, 0) * (p.WH_INVENTORY + p.PO_QTY_TOTAL), 0) - COALESCE(ws.WH_QTY, 0), 0 ) AS RAW_GAP FROM sku_po p LEFT JOIN wh_size ws ON ws.SKU_GROUP = p.SKU_GROUP LEFT JOIN hist_mix hm ON hm.SKU_GROUP = p.SKU_GROUP AND hm.SIZE = ws.SIZE ), wh_mix AS ( SELECT SKU_GROUP, SIZE, WH_QTY * 1.0 / NULLIF(SUM(WH_QTY) OVER (PARTITION BY SKU_GROUP), 0) AS CURRENT_WH_MIX_PCT FROM wh_size ) SELECT sc.SKU_GROUP, sc.SKU_FAMILY, sc.TYPE, sc.SUBTYPE, sc.TITLE, sc.IMAGE_URL, sc.FINAL_SKU_CLASS, sc.WH_INVENTORY, sc.TOTAL_STORE_INVENTORY, sc.TOTAL_INVENTORY, ROUND(sc.SUM_DAILY_ROS, 2) AS SUM_DAILY_ROS, sc.DEMAND_90D, sc.PO_QTY_TOTAL, CASE WHEN sc.PO_QTY_TOTAL > 0 THEN \'Yes\' ELSE \'No\' END AS PO_REQUIRED_FLAG, sc.SIZE, sc.HIST_SOLD_90D, ROUND(sc.HIST_MIX_PCT * 100, 2) AS HIST_MIX_PCT, sc.CURRENT_WH_QTY, ROUND(COALESCE(wm.CURRENT_WH_MIX_PCT, 0) * 100, 2) AS CURRENT_WH_MIX_PCT, sc.TARGET_POST_PO_QTY, CASE WHEN sc.PO_QTY_TOTAL = 0 THEN 0 WHEN SUM(sc.RAW_GAP) OVER (PARTITION BY sc.SKU_GROUP) = 0 THEN ROUND(sc.PO_QTY_TOTAL * sc.HIST_MIX_PCT, 0) ELSE ROUND(sc.PO_QTY_TOTAL * sc.RAW_GAP / SUM(sc.RAW_GAP) OVER (PARTITION BY sc.SKU_GROUP), 0) END AS SIZE_PO_QTY FROM size_calc sc LEFT JOIN wh_mix wm ON wm.SKU_GROUP = sc.SKU_GROUP AND wm.SIZE = sc.SIZE ORDER BY sc.SKU_GROUP, CASE sc.SIZE WHEN \'XS\' THEN 1 WHEN \'S\' THEN 2 WHEN \'M\' THEN 3 WHEN \'L\' THEN 4 WHEN \'XL\' THEN 5 WHEN \'XXL\' THEN 6 WHEN \'3XL\' THEN 7 WHEN \'4XL\' THEN 8 WHEN \'5XL\' THEN 9 WHEN \'6XL\' THEN 10 END;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            